        // starts at the base image origin (canvasEdgeInset = 24).
        let centerX = 60 - 24
        let centerY = 50 - 24
        var foundFill = false
        var foundContrast = false
        for dy in -10...10 {
            for dx in -10...10 {
                guard let pixel = rep.colorAt(x: centerX + dx, y: centerY + dy)?.usingColorSpace(.deviceRGB) else { continue }
                if pixel.redComponent > 0.8 && pixel.greenComponent < 0.4 && pixel.blueComponent < 0.4 {
