private var defaultTextFontSize: CGFloat {
    let targetOnScreenSize: CGFloat = 38.4
    let normalizedZoom = max(0.01, textCreationZoomFactor)
    return round(targetOnScreenSize / normalizedZoom)
}

rawInput.new_string:
private var defaultTextFontSize: CGFloat {
    let targetOnScreenSize: CGFloat = 38.4
    let normalizedZoom = max(0.01, textCreationZoomFactor)
    // Cap at the persisted-state font limit so extreme downscale fits can
    // never produce an unsafe save size.
    return min(round(targetOnScreenSize / normalizedZoom), ImageSafetyLimits.runtime.maxFontSize)
}

